pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        // fund the contract so it can send Ether
        address owner = address(uint160(uint256(keccak256("owner"))));
        vm.deal(owner, amount);
        vm.prank(owner);
        // start as owner by deploying via constructor? constructor sets owner = msg.sender
        // we need to call as the actual owner deployed in setUp, which is address(this)
        // So: use the contract's own address as owner
        vm.prank(address(this));
        uint256 balanceBefore = address(c).balance;
        // we need to provide value to c so it can transfer out; send Ether with the call
        vm.deal(address(this), amount);
        c.sendTo{value: amount}(receiver, amount);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter < balanceBefore);
    }
}

